// WP-5.4 compute software rasteriser: see include/fuse/renderer/swraster/swraster.hpp.
#include <fuse/renderer/swraster/swraster.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <cmath>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp54.cmake from shaders/swraster/*: kSwRaster<Kernel><Slang|Glsl>Spv and
// FUSE_SWRASTER_{SLANG,GLSL} when every kernel of a language exists.
#include "swraster_spv.h"
#endif

namespace fuse::renderer::swraster {

namespace {
constexpr u32 kPushBytes = sizeof(SwRasterPush);
/// Counts reset at the start of every frame: dispatches {0, 1, 1}, HW draws {372, 0, 0, 0}, counters 0.
constexpr u32 kCountReset[kSwCountWords] = {0u, 1u, 1u, 0u, 1u, 1u, 0u, 1u, 1u, 0u, 1u, 1u, kSwHwVertices, 0u, 0u, 0u,
                                            kSwHwVertices, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u};
constexpr u64 kCountBytes = sizeof(kCountReset);
/// vkCmdDispatchIndirect x is capped at the guaranteed maxComputeWorkGroupCount[0].
constexpr u32 kMaxCapacity = 65535u;

enum RefIndex : u32 { kRefGroups = 0, kRefSoftware, kRefHardware, kRefCounts, kRefResults, kRefConstants };

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
struct KernelSet {
    Code expand, classify, rasterImage, rasterBuffer, hwVs, hwFsImage, hwFsBuffer;
};
#endif
} // namespace

SwRasterCapabilities querySwRasterCapabilities(const VulkanDevice* device) {
    SwRasterCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const visbuffer::VisCapabilities vis = visbuffer::queryVisCapabilities(device);
    if (!vis.atomicBuffer && !vis.atomicImage) {
        c.reason = vis.atomicReason;
        return c;
    }
    c.usable = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

void swRasterThresholds(f32 triangleThresholdPixels, f32 maxClusterPixels, u32& triangleThreshold, u32& maxClusterExtent) {
    auto toSubpixels = [](f32 px, f32 maxPx) {
        const f32 v = px > 0.f ? (px < maxPx ? px : maxPx) : 0.f; // NaN -> 0
        return static_cast<u32>(std::floor(v * static_cast<f32>(kSwSubpixelOne) + 0.5f));
    };
    triangleThreshold = toSubpixels(triangleThresholdPixels, 64.f);
    maxClusterExtent = toSubpixels(maxClusterPixels, static_cast<f32>(kSwMaxClusterPixels));
}

SwRasterizer::~SwRasterizer() { destroy(); }

bool SwRasterizer::init(const SwRasterDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.vis == nullptr ||
        !desc.vis->valid() || desc.vis->mode() != visbuffer::VisMode::Atomic64 ||
        !querySwRasterCapabilities(desc.device).usable) {
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    m_capacity = desc.clusterCapacity < kMaxCapacity ? desc.clusterCapacity : kMaxCapacity;
    m_capacity = m_capacity > 0u ? m_capacity : 1u;
    const u32 frames = desc.framesInFlight > 0u ? desc.framesInFlight : 1u;
    const u64 listBytes = 2ull * m_capacity * sizeof(SwCluster);
    const bool ok = createPipelines() &&
                    createBuffer(m_groups, 2ull * m_capacity * sizeof(SwGroup), false, false, "swraster.groups") &&
                    createBuffer(m_software, listBytes, false, false, "swraster.software") &&
                    createBuffer(m_hardware, listBytes, false, false, "swraster.hardware") &&
                    createBuffer(m_counts, kCountBytes, true, false, "swraster.counts") &&
                    createBuffer(m_constantsRing, static_cast<u64>(frames) * sizeof(SwRasterConstants), false, true,
                                 "swraster.constants") &&
                    (!desc.results ||
                     createBuffer(m_results, 2ull * m_capacity * kSwGroupSize * sizeof(u32), false, false, "swraster.results"));
    if (!ok) {
        destroy();
        return false;
    }
    m_stats.capacity = m_capacity;
    return true;
#else
    return false;
#endif
}

void SwRasterizer::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    for (OwnedBuffer* b : {&m_groups, &m_software, &m_hardware, &m_counts, &m_results, &m_constantsRing}) {
        destroyBuffer(*b);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void* pipeline : {m_expandPipeline, m_classifyPipeline, m_rasterPipeline, m_hardwarePipeline}) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
        }
    }
    for (void* layout : {m_computeLayout, m_graphicsLayout}) {
        if (layout != nullptr) {
            vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(layout), nullptr);
        }
    }
#endif
    m_expandPipeline = m_classifyPipeline = m_rasterPipeline = m_hardwarePipeline = nullptr;
    m_computeLayout = m_graphicsLayout = nullptr;
    m_language = "none";
    m_capacity = 0;
    m_ringSlot = 0;
    m_constantsAddress = 0;
    m_constants = SwRasterConstants{};
    for (u8& q : m_queues) {
        q = rg::kNoQueue;
    }
    m_stats = SwRasterStats{};
    m_initialized = false;
}

bool SwRasterizer::createBuffer(OwnedBuffer& out, u64 bytes, bool indirect, bool hostVisible, const char* name) {
    out = OwnedBuffer{};
    BufferDesc desc{};
    desc.size = static_cast<usize>(bytes);
    desc.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::TransferDst) |
                                          static_cast<u32>(BufferUsage::TransferSrc) |
                                          static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                          (indirect ? static_cast<u32>(BufferUsage::Indirect) : 0u));
    desc.memoryUsage = hostVisible ? MemoryUsage::CpuToGpu : MemoryUsage::GpuOnly;
    desc.name = name;
    if (!m_desc.allocator->createBuffer(desc, out.buffer) || out.buffer.deviceAddress == 0u ||
        (hostVisible && out.buffer.mapped == nullptr)) {
        if (out.buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(out.buffer);
        }
        out = OwnedBuffer{};
        return false;
    }
    out.slot = m_desc.bindless->registerBufferSlot(out.buffer, false);
    out.handle = m_desc.bindless->shaderHandle(out.slot);
    return out.slot.isValid();
}

void SwRasterizer::destroyBuffer(OwnedBuffer& buffer) {
    if (buffer.slot.isValid()) {
        m_desc.bindless->unregisterSlot(buffer.slot);
    }
    if (buffer.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(buffer.buffer);
    }
    buffer = OwnedBuffer{};
}

bool SwRasterizer::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    KernelSet k{};
    bool found = false;
#if defined(FUSE_SWRASTER_SLANG)
    if (m_desc.language == SwRasterKernelLanguage::Auto || m_desc.language == SwRasterKernelLanguage::Slang) {
        k = KernelSet{code(kSwRasterExpandSlangSpv),      code(kSwRasterClassifySlangSpv), code(kSwRasterRasterImageSlangSpv),
                      code(kSwRasterRasterBufferSlangSpv), code(kSwRasterHwVsSlangSpv),     code(kSwRasterHwFsImageSlangSpv),
                      code(kSwRasterHwFsBufferSlangSpv)};
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_SWRASTER_GLSL)
    if (!found && (m_desc.language == SwRasterKernelLanguage::Auto || m_desc.language == SwRasterKernelLanguage::Glsl)) {
        k = KernelSet{code(kSwRasterExpandGlslSpv),      code(kSwRasterClassifyGlslSpv), code(kSwRasterRasterImageGlslSpv),
                      code(kSwRasterRasterBufferGlslSpv), code(kSwRasterHwVsGlslSpv),     code(kSwRasterHwFsImageGlslSpv),
                      code(kSwRasterHwFsBufferGlslSpv)};
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    auto makeLayout = [&](VkShaderStageFlags stages, void*& out) {
        VkPushConstantRange range{stages, 0, kPushBytes};
        VkPipelineLayoutCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        info.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
        info.pSetLayouts = &setLayout;
        info.pushConstantRangeCount = 1;
        info.pPushConstantRanges = &range;
        VkPipelineLayout layout = VK_NULL_HANDLE;
        const bool ok = vkCreatePipelineLayout(device, &info, nullptr, &layout) == VK_SUCCESS;
        out = layout;
        return ok;
    };
    if (!makeLayout(VK_SHADER_STAGE_COMPUTE_BIT, m_computeLayout) ||
        !makeLayout(VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, m_graphicsLayout)) {
        return false;
    }
    auto module = [&](const Code& c) {
        VkShaderModuleCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        info.codeSize = c.bytes;
        info.pCode = c.words;
        VkShaderModule m = VK_NULL_HANDLE;
        vkCreateShaderModule(device, &info, nullptr, &m);
        return m;
    };
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    const bool image = m_desc.vis->atomicTarget() == visbuffer::VisAtomicTarget::Image;
    auto compute = [&](const Code& c, void*& out) {
        VkShaderModule m = module(c);
        if (m == VK_NULL_HANDLE) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = m;
        info.stage.pName = "main";
        info.layout = static_cast<VkPipelineLayout>(m_computeLayout);
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, m, nullptr);
        out = pipeline;
        return result == VK_SUCCESS;
    };
    if (!compute(k.expand, m_expandPipeline) || !compute(k.classify, m_classifyPipeline) ||
        !compute(image ? k.rasterImage : k.rasterBuffer, m_rasterPipeline)) {
        return false;
    }
    // Hardware cluster path: vertex + fragment, no attachments (atomic writes only).
    VkShaderModule vs = module(k.hwVs);
    VkShaderModule fs = module(image ? k.hwFsImage : k.hwFsBuffer);
    if (vs == VK_NULL_HANDLE || fs == VK_NULL_HANDLE) {
        vkDestroyShaderModule(device, vs, nullptr);
        vkDestroyShaderModule(device, fs, nullptr);
        return false;
    }
    VkPipelineShaderStageCreateInfo stages[2]{};
    stages[0].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
    stages[0].module = vs;
    stages[0].pName = "main";
    stages[1].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
    stages[1].module = fs;
    stages[1].pName = "main";
    VkPipelineVertexInputStateCreateInfo vertexInput{};
    vertexInput.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
    VkPipelineInputAssemblyStateCreateInfo assembly{};
    assembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
    assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
    VkPipelineViewportStateCreateInfo viewport{};
    viewport.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
    viewport.viewportCount = 1;
    viewport.scissorCount = 1;
    VkPipelineRasterizationStateCreateInfo rasterization{};
    rasterization.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
    rasterization.polygonMode = VK_POLYGON_MODE_FILL;
    rasterization.cullMode = VK_CULL_MODE_NONE; // == the WP-1.4 pipelines (two-sided)
    rasterization.lineWidth = 1.f;
    VkPipelineMultisampleStateCreateInfo multisample{};
    multisample.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
    multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
    VkPipelineDepthStencilStateCreateInfo depth{};
    depth.sType = VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO;
    VkPipelineColorBlendStateCreateInfo blend{};
    blend.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
    const VkDynamicState dynamics[2] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
    VkPipelineDynamicStateCreateInfo dynamic{};
    dynamic.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
    dynamic.dynamicStateCount = 2;
    dynamic.pDynamicStates = dynamics;
    VkPipelineRenderingCreateInfo rendering{};
    rendering.sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO;
    VkGraphicsPipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
    info.pNext = &rendering;
    info.flags = createFlags;
    info.stageCount = 2;
    info.pStages = stages;
    info.pVertexInputState = &vertexInput;
    info.pInputAssemblyState = &assembly;
    info.pViewportState = &viewport;
    info.pRasterizationState = &rasterization;
    info.pMultisampleState = &multisample;
    info.pDepthStencilState = &depth;
    info.pColorBlendState = &blend;
    info.pDynamicState = &dynamic;
    info.layout = static_cast<VkPipelineLayout>(m_graphicsLayout);
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, vs, nullptr);
    vkDestroyShaderModule(device, fs, nullptr);
    m_hardwarePipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool SwRasterizer::beginFrame(u64 frameSerial, const SwRasterFrameDesc& frame, const culling::InstanceCuller& culler) {
    if (!m_initialized) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_stats.phases = 0;
    const visbuffer::VisBuffer& vis = *m_desc.vis;
    const culling::CullConstants& cull = culler.constants();
    SwRasterConstants& c = m_constants;
    std::memcpy(c.viewProj, frame.viewProj, sizeof(c.viewProj));
    c.scene = frame.sceneHandle;
    c.width = vis.width();
    c.height = vis.height();
    c.flags = (frame.results && m_results.handle != 0u ? static_cast<u32>(kSwFlagWriteResults) : 0u) |
              (frame.skipSoftware ? static_cast<u32>(kSwFlagSkipSoftware) : 0u) |
              (frame.skipHardware ? static_cast<u32>(kSwFlagSkipHardware) : 0u);
    c.mode = frame.mode == SwRasterMode::ForceSoftware   ? static_cast<u32>(kSwModeForceSoftware)
             : frame.mode == SwRasterMode::ForceHardware ? static_cast<u32>(kSwModeForceHardware)
                                                         : static_cast<u32>(kSwModeClassify);
    swRasterThresholds(frame.triangleThresholdPixels, frame.maxClusterPixels, c.triangleThreshold, c.maxClusterExtent);
    c.capacity = m_capacity;
    c.groupsBuffer = m_groups.handle;
    c.swBuffer = m_software.handle;
    c.hwBuffer = m_hardware.handle;
    c.countsBuffer = m_counts.handle;
    c.resultsBuffer = m_results.handle;
    c.target64 = vis.target64Handle();
    c.cullArgsBuffer = cull.argsBuffer;
    c.cullCountsBuffer = cull.countsBuffer;
    c.phase2DrawBase = cull.phase2DrawBase;
    c.maxDraws = cull.maxDraws;
    const u32 frames = static_cast<u32>(m_constantsRing.buffer.desc.size / sizeof(SwRasterConstants));
    m_ringSlot = frames > 0u ? (m_ringSlot + 1u) % frames : 0u;
    const u64 offset = static_cast<u64>(m_ringSlot) * sizeof(SwRasterConstants);
    std::memcpy(static_cast<u8*>(m_constantsRing.buffer.mapped) + offset, &c, sizeof(SwRasterConstants));
    m_constantsAddress = m_constantsRing.buffer.deviceAddress + offset;
    return c.width > 0u && c.height > 0u && c.target64 != 0u;
}

SwRasterGraphRefs SwRasterizer::importInto(rg::Graph& graph) {
    SwRasterGraphRefs refs{};
    if (!m_initialized) {
        return refs;
    }
    auto import = [&](OwnedBuffer& b, u32 index, const char* name) {
        if (b.buffer.handle == nullptr) {
            return rg::BufferRef{};
        }
        return graph.importBuffer(rg::ImportedBuffer{b.buffer.handle, b.buffer.desc.size, m_queues[index], &m_queues[index], name});
    };
    refs.groups = import(m_groups, kRefGroups, "swraster.groups");
    refs.software = import(m_software, kRefSoftware, "swraster.software");
    refs.hardware = import(m_hardware, kRefHardware, "swraster.hardware");
    refs.counts = import(m_counts, kRefCounts, "swraster.counts");
    refs.results = import(m_results, kRefResults, "swraster.results");
    refs.constants = import(m_constantsRing, kRefConstants, "swraster.constants");
    return refs;
}

void SwRasterizer::addDraw(rg::Graph& graph, const SwRasterGraphRefs& refs, const visbuffer::VisGraphRefs& vis,
                           const gpu_scene::GpuSceneGraphRefs& scene, const culling::InstanceCuller& culler,
                           const culling::CullGraphRefs& cullRefs, culling::CullPhase phase) {
    if (!m_initialized || !refs.counts.valid() || m_stats.phases >= 2u) {
        return;
    }
    const bool phase1 = phase == culling::CullPhase::Phase1;
    const u32 region = phase1 ? 0u : 1u;
    ++m_stats.phases;
    const u64 regionBytes = static_cast<u64>(m_capacity) * sizeof(SwCluster);
    const rg::BufferRange regionRange{static_cast<u64>(region) * regionBytes, regionBytes};
    auto record = [&](u32 slot, u8 kind, u32 groups) -> PassRecord* {
        PassRecord& r = m_passes[region * 4u + slot];
        r.self = this;
        r.push = SwRasterPush{};
        r.push.constants = m_constantsAddress;
        r.push.region = region;
        r.kind = kind;
        r.groups = groups;
        return &r;
    };
    auto useTarget = [&](rg::PassBuilder& pass, u8 stage) {
        if (vis.image64.valid()) {
            pass.use(vis.image64, rg::Access::StorageReadWrite, {}, stage);
        }
        if (vis.buffer64.valid()) {
            pass.use(vis.buffer64, rg::Access::StorageReadWrite, {}, stage);
        }
    };
    if (phase1) {
        graph.addPass("swraster.reset", &SwRasterizer::recordReset, this).use(refs.counts, rg::Access::TransferDst);
    }
    // Expand: the culler's phase draws -> classify records of this region + the classify dispatch.
    {
        PassRecord* r = record(0u, kPassExpand, (culler.capacity() + kSwExpandWorkgroup - 1u) / kSwExpandWorkgroup);
        rg::PassBuilder pass = graph.addPass(phase1 ? "swraster.expand1" : "swraster.expand2", &SwRasterizer::recordPass, r);
        gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
        pass.use(refs.constants, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.counts, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.groups, rg::Access::StorageWrite, regionRange, rg::kStageCompute)
            .use(cullRefs.args, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(cullRefs.counts, rg::Access::StorageRead, {}, rg::kStageCompute);
    }
    if (phase1) {
        m_desc.vis->addClear(graph, vis);
    }
    // Classify: records -> SW / HW lists.
    {
        PassRecord* r = record(1u, kPassClassify, 0u);
        rg::PassBuilder pass = graph.addPass(phase1 ? "swraster.classify1" : "swraster.classify2", &SwRasterizer::recordPass, r);
        gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
        pass.use(refs.constants, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.counts, rg::Access::IndirectRead)
            .use(refs.counts, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.groups, rg::Access::StorageRead, regionRange, rg::kStageCompute)
            .use(refs.software, rg::Access::StorageWrite, regionRange, rg::kStageCompute)
            .use(refs.hardware, rg::Access::StorageWrite, regionRange, rg::kStageCompute);
        if (refs.results.valid()) {
            const u64 bytes = static_cast<u64>(m_capacity) * kSwGroupSize * sizeof(u32);
            pass.use(refs.results, rg::Access::StorageWrite, rg::BufferRange{region * bytes, bytes}, rg::kStageCompute);
        }
    }
    // Software: SW clusters -> atomicMin into the target (demotions append to the HW list).
    {
        PassRecord* r = record(2u, kPassSoftware, 0u);
        rg::PassBuilder pass = graph.addPass(phase1 ? "swraster.sw1" : "swraster.sw2", &SwRasterizer::recordPass, r);
        gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
        pass.use(refs.constants, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(refs.counts, rg::Access::IndirectRead)
            .use(refs.counts, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.software, rg::Access::StorageRead, regionRange, rg::kStageCompute)
            .use(refs.hardware, rg::Access::StorageReadWrite, regionRange, rg::kStageCompute);
        useTarget(pass, rg::kStageCompute);
    }
    // Hardware: HW clusters through the vertex pipeline, fragment atomicMin into the same target.
    {
        PassRecord* r = record(3u, kPassHardware, 0u);
        rg::PassBuilder pass = graph.addPass(phase1 ? "swraster.hw1" : "swraster.hw2", &SwRasterizer::recordPass, r);
        constexpr u8 kVertexFragment = static_cast<u8>(rg::kStageVertex | rg::kStageFragment);
        gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageVertex);
        pass.use(refs.constants, rg::Access::StorageRead, {}, kVertexFragment)
            .use(refs.counts, rg::Access::IndirectRead)
            .use(refs.hardware, rg::Access::StorageRead, regionRange, rg::kStageVertex);
        useTarget(pass, rg::kStageFragment);
    }
}

void SwRasterizer::addCulledFrame(rg::Graph& graph, const SwRasterGraphRefs& refs, const visbuffer::VisGraphRefs& vis,
                                  const gpu_scene::GpuSceneGraphRefs& scene, u32 sceneHandle, culling::InstanceCuller& culler,
                                  const culling::CullGraphRefs& cullRefs) {
    if (!m_initialized) {
        return;
    }
    visbuffer::VisBuffer& vb = *m_desc.vis;
    culler.addPhase1(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, vis, scene, culler, cullRefs, culling::CullPhase::Phase1);
    vb.addExport(graph, vis);
    culler.addHizBuild(graph, cullRefs, vis.depth, vb.depthSampledHandle());
    culler.addPhase2(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, vis, scene, culler, cullRefs, culling::CullPhase::Phase2);
    vb.addExport(graph, vis);
    culler.addHizBuild(graph, cullRefs, vis.depth, vb.depthSampledHandle());
}

void SwRasterizer::recordReset(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const SwRasterizer& self = *static_cast<const SwRasterizer*>(user);
    vkCmdUpdateBuffer(static_cast<VkCommandBuffer>(context.commandBuffer), static_cast<VkBuffer>(self.m_counts.buffer.handle), 0,
                      kCountBytes, kCountReset);
#else
    (void)context;
    (void)user;
#endif
}

void SwRasterizer::recordPass(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const SwRasterizer& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const VkBuffer counts = static_cast<VkBuffer>(self.m_counts.buffer.handle);
    const u32 region = r.push.region;
    if (r.kind == kPassHardware) {
        const u32 width = self.m_constants.width;
        const u32 height = self.m_constants.height;
        VkRenderingInfo rendering{};
        rendering.sType = VK_STRUCTURE_TYPE_RENDERING_INFO;
        rendering.renderArea.extent = {width, height};
        rendering.layerCount = 1;
        vkCmdBeginRendering(cmd, &rendering);
        const VkPipelineLayout layout = static_cast<VkPipelineLayout>(self.m_graphicsLayout);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, static_cast<VkPipeline>(self.m_hardwarePipeline));
        self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, self.m_graphicsLayout, 0);
        const VkViewport viewport{0.f, 0.f, static_cast<f32>(width), static_cast<f32>(height), 0.f, 1.f};
        const VkRect2D scissor{{0, 0}, {width, height}};
        vkCmdSetViewport(cmd, 0, 1, &viewport);
        vkCmdSetScissor(cmd, 0, 1, &scissor);
        vkCmdPushConstants(cmd, layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, kPushBytes, &r.push);
        vkCmdDrawIndirect(cmd, counts, static_cast<VkDeviceSize>(kSwCountHardware0 + region * 4u) * sizeof(u32), 1,
                          static_cast<u32>(sizeof(VkDrawIndirectCommand)));
        vkCmdEndRendering(cmd);
        return;
    }
    void* pipeline = r.kind == kPassExpand ? self.m_expandPipeline : r.kind == kPassClassify ? self.m_classifyPipeline : self.m_rasterPipeline;
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_computeLayout, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_computeLayout), VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes, &r.push);
    if (r.kind == kPassExpand) {
        if (r.groups > 0u) {
            vkCmdDispatch(cmd, r.groups, 1, 1);
        }
        return;
    }
    const u32 word = r.kind == kPassClassify ? kSwCountClassify0 + region * 3u : kSwCountSoftware0 + region * 3u;
    vkCmdDispatchIndirect(cmd, counts, static_cast<VkDeviceSize>(word) * sizeof(u32));
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::swraster
